examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchCopyField({{fields.0.label}}, value: {{fields.0.value}}, isLabelHidden: true)
    MonarchCopyField(
        {{fields.1.label}},
        value: {{fields.1.value}},
        size: .{{fields.1.size|raw}},
        isIconOnly: {{fields.1.iconOnly}},
        isLabelHidden: true
    )
}

